import { createReadStream } from "node:fs";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { env } from "../env.js";

// Local-disk storage for uploads. Keys are generated by us ("<userId>/<uuid>"), never taken
// from user input, so they can't escape the root. Swap this module for S3 when deploying wide.

const root = path.resolve(env.DATA_DIR, "files");

const resolveKey = (key: string) => {
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error("Invalid storage key");
  return full;
};

export async function putFile(key: string, data: Buffer) {
  const full = resolveKey(key);
  await mkdir(path.dirname(full), { recursive: true });
  await writeFile(full, data);
}

export const readFileStream = (key: string) => createReadStream(resolveKey(key));

export const readFileBuffer = (key: string) => readFile(resolveKey(key));

/** Best effort: a leftover file is harmless, a failed request because of one is not. */
export async function removeFiles(keys: string[]) {
  await Promise.all(keys.map((key) => rm(resolveKey(key), { force: true }).catch(() => {})));
}
